  dglL: "Proceso:", dg_wachs: "Crecimiento (bacterias)", dg_zerfall: "Desintegración (medicamento en sangre)", dg_kuehl: "Enfriamiento (té)", dg_logist: "Crecimiento limitado (rumor)",
